if PY2:
    def has_1pos_and_kwonly(func):
        """Check if func has exactly 1 positional argument and keyword-only args."""
        spec = inspect.getargspec(func)
        return len(spec.args) == 1 and (bool(spec.defaults) or bool(spec.keywords))
else:
    def has_1pos_and_kwonly(func):
        """Check if func has exactly 1 positional argument and keyword-only args."""
        spec = inspect.signature(func)
        params = spec.parameters.values()
        pos_count = sum(1 for p in params
                        if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD))
        kwonly_count = sum(1 for p in params
                           if p.kind == p.KEYWORD_ONLY)
        return pos_count == 1 and kwonly_count > 0

